import{c as e,Q as a,j as s,m as n}from"./chunks/framework.t4rEqR7d.js";const g=JSON.parse('{"title":"Desktop app","description":"","frontmatter":{},"headers":[],"relativePath":"desktop.md","filePath":"desktop.md"}'),o={name:"desktop.md"};function i(r,t,l,d,p,h){return a(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="desktop-app" tabindex="-1">Desktop app <a class="header-anchor" href="#desktop-app" aria-label="Permalink to &quot;Desktop app&quot;">​</a></h1><p>Language: <a href="/pagent/zh/desktop.html">中文</a> | English</p><p><strong>pagent Desktop</strong> is a desktop workbench for talking to an AI agent: session history on the left, chat in the center, sandbox files and generated artifacts on the right.</p><p>This page is for <strong>end users</strong> — download, API key, first task, everyday controls. To hack on the app itself, see the <a href="https://github.com/SyncLionPaw/pagent/blob/main/editors/desktop/README.md" target="_blank" rel="noreferrer">developer README</a>.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><h3 id="_1-install-the-backend-required" tabindex="-1">1. Install the backend (required) <a class="header-anchor" href="#_1-install-the-backend-required" aria-label="Permalink to &quot;1. Install the backend (required)&quot;">​</a></h3><p>Desktop needs the <code>pagent</code> command on your machine (same as the VS Code extension):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tool</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pagent</span></span></code></pre></div><p>If the app later says it cannot start the backend, make sure <code>pagent</code> is on your <code>PATH</code>, or reinstall with the command above.</p><h3 id="_2-download-the-app" tabindex="-1">2. Download the app <a class="header-anchor" href="#_2-download-the-app" aria-label="Permalink to &quot;2. Download the app&quot;">​</a></h3><p>Get the desktop build from <a href="https://github.com/SyncLionPaw/pagent/releases" target="_blank" rel="noreferrer">pagent GitHub Releases</a>:</p><ul><li><strong>macOS (Apple Silicon)</strong> — <code>pagent-Desktop-&lt;version&gt;-arm64.zip</code>, or <code>pagent Desktop.app</code> inside the release assets.</li></ul><p>Unzip and move <strong>pagent Desktop</strong> into <strong>Applications</strong>.</p><h3 id="macos-says-the-app-is-damaged" tabindex="-1">macOS says the app is “damaged”? <a class="header-anchor" href="#macos-says-the-app-is-damaged" aria-label="Permalink to &quot;macOS says the app is “damaged”?&quot;">​</a></h3><p>Downloads from GitHub get a <strong>quarantine</strong> flag. Unsigned apps often show <em>“pagent Desktop is damaged and can’t be opened”</em> — the build is usually fine.</p><p><strong>Fix (recommended)</strong> — run in Terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -cr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/Applications/pagent Desktop.app&quot;</span></span></code></pre></div><p>Then open the app normally. The zip also includes <strong><code>打开说明.txt</code></strong> (Chinese open instructions).</p><p><strong>Right-click → Open</strong> works for some Gatekeeper prompts but not always for the “damaged” message; prefer <code>xattr</code> above.</p><p><strong>Windows / Linux</strong> builds are not published yet. Use the <a href="./vscode.html">VS Code extension</a> or the <code>pagent</code> CLI.</p><h2 id="before-your-first-message-api-key" tabindex="-1">Before your first message: API key <a class="header-anchor" href="#before-your-first-message-api-key" aria-label="Permalink to &quot;Before your first message: API key&quot;">​</a></h2><p><strong>On first launch</strong>, if pagent or an API key is missing, a blocking <strong>Setup</strong> wizard opens (environment → API key → sandbox) — the main UI stays locked until those are ready. Reopen the wizard anytime from the user menu → <strong>Setup</strong>. The <strong>environment health check</strong> in Settings is separate: status lights and disk usage, not a wizard.</p><p>It checks:</p><ul><li><code>uv</code> / <code>pagent</code> on PATH (one-click install or copy commands)</li><li>API key (writes <code>~/.pagent/pagent.toml</code>)</li><li>Optional: <code>docker</code> / <code>podman</code> and the <code>pagent:latest</code> image (for container sandbox only)</li></ul><p>Choose <strong>Set up later</strong> to skip; you still need a key before chatting.</p><p>Without the wizard, configure a key manually:</p><p><strong>Environment variable:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> DEEPSEEK_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sk-...</span></span></code></pre></div><p><strong>Config file (recommended):</strong> create <code>~/.pagent/pagent.toml</code>:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">provider</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">api_key = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sk-...&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;deepseek-v4-flash&quot;</span></span></code></pre></div><p>More providers: <a href="./guide/providers.html">Providers &amp; API keys</a>.</p><p>If the key is missing, you will see an error after you send a message. Open <strong>Settings</strong> (gear) for an <strong>environment health check</strong> (status lights + disk usage for <code>~/.pagent</code> and the sandbox image) and a read-only overview of <code>pagent.toml</code> — edit the file in a text editor to change values.</p><h2 id="first-launch" tabindex="-1">First launch <a class="header-anchor" href="#first-launch" aria-label="Permalink to &quot;First launch&quot;">​</a></h2><ol><li>Open <strong>pagent Desktop</strong>.</li><li>The app starts the backend automatically and tries to <strong>resume your latest conversation</strong> for the current project.</li><li>To start fresh, click <strong>New task</strong> in the sidebar.</li></ol><h3 id="create-a-task" tabindex="-1">Create a task <a class="header-anchor" href="#create-a-task" aria-label="Permalink to &quot;Create a task&quot;">​</a></h3><p>In the <strong>New task</strong> dialog:</p><table tabindex="0"><thead><tr><th>Field</th><th>What to pick</th></tr></thead><tbody><tr><td><strong>Sandbox</strong></td><td><strong>local</strong> — runs on your Mac, no Docker needed (default)</td></tr><tr><td><strong>Project folder</strong></td><td>The folder on disk you want the agent to work with</td></tr></tbody></table><p>Click <strong>Create session</strong>, type in the box at the bottom, press <strong>Enter</strong> to send (<strong>Shift+Enter</strong> for a new line).</p><h2 id="main-window" tabindex="-1">Main window <a class="header-anchor" href="#main-window" aria-label="Permalink to &quot;Main window&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────┬──────────────────────┬─────────────┐</span></span>
<span class="line"><span>│  Sessions   │       Chat           │  Files &amp;    │</span></span>
<span class="line"><span>│             │                      │  artifacts  │</span></span>
<span class="line"><span>└─────────────┴──────────────────────┴─────────────┘</span></span></code></pre></div><ul><li><strong>Left</strong> — past chats; click one to continue.</li><li><strong>Center</strong> — messages, tool steps, composer.</li><li><strong>Right</strong> — sandbox tree, project files, outputs (HTML, PDF, etc.), log.</li></ul><p>Drag the edges to resize. Press <strong>⌘K</strong> (or the <strong>?</strong> button) for shortcuts.</p><h2 id="composer" tabindex="-1">Composer <a class="header-anchor" href="#composer" aria-label="Permalink to &quot;Composer&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Control</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Send / Stop</strong></td><td>Send; while the agent is running, becomes <strong>Stop</strong> to cancel</td></tr><tr><td><strong>Lightning (YOLO)</strong></td><td>Auto-approve tool calls — use only when you trust the task</td></tr><tr><td><strong>Ring</strong></td><td>Rough context usage vs model limit</td></tr><tr><td><strong>@</strong></td><td>Insert a file from your project or sandbox into the message</td></tr></tbody></table><h2 id="settings-help" tabindex="-1">Settings &amp; help <a class="header-anchor" href="#settings-help" aria-label="Permalink to &quot;Settings &amp; help&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Where</th><th>What</th></tr></thead><tbody><tr><td><strong>Gear</strong></td><td>Environment health check (status lights + disk usage) + view <code>pagent.toml</code></td></tr><tr><td><strong>Book icon</strong></td><td>Open this documentation site in the browser</td></tr><tr><td><strong>User menu → Scan docs</strong></td><td>QR code for the docs on your phone</td></tr></tbody></table><p>To change model or advanced sandbox options, edit <code>pagent.toml</code> in a text editor.</p><h2 id="where-files-go" tabindex="-1">Where files go <a class="header-anchor" href="#where-files-go" aria-label="Permalink to &quot;Where files go&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.pagent/</span></span>
<span class="line"><span>├── pagent.toml       # your API key and model</span></span>
<span class="line"><span>├── threads/          # conversation history</span></span>
<span class="line"><span>└── skills/           # optional local skills</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;your project&gt;/</span></span>
<span class="line"><span>└── artifacts/        # files the agent generated (HTML, etc.)</span></span></code></pre></div><p>Do not share or commit <code>pagent.toml</code> if it contains a real API key.</p><h2 id="something-wrong" tabindex="-1">Something wrong? <a class="header-anchor" href="#something-wrong" aria-label="Permalink to &quot;Something wrong?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>Try</th></tr></thead><tbody><tr><td>“Bridge” or backend won’t start</td><td>Run <code>uv tool install pagent</code>; check the log panel on the right</td></tr><tr><td>Error after sending</td><td>Add API key to <code>pagent.toml</code> or <code>DEEPSEEK_API_KEY</code></td></tr><tr><td>“Damaged, can’t be opened”</td><td>Run <code>xattr -cr &quot;/Applications/pagent Desktop.app&quot;</code> (see above)</td></tr><tr><td>Settings says no config file</td><td>Create <code>~/.pagent/pagent.toml</code> as above</td></tr><tr><td>Tool stuck on “running”</td><td>Tap <strong>Stop</strong>, or send again; recent versions fix stale tool cards on reload</td></tr></tbody></table><h2 id="also-useful" tabindex="-1">Also useful <a class="header-anchor" href="#also-useful" aria-label="Permalink to &quot;Also useful&quot;">​</a></h2><ul><li><a href="./vscode.html">VS Code extension</a> — same agent inside VS Code, with guided first-run setup</li><li><a href="./guide/install.html">Install CLI</a> — if <code>uv</code> is not installed yet</li></ul>`,54)])])}const u=e(o,[["render",i]]);export{g as __pageData,u as default};
